//////////////////////////////////////////////////////////////////////////////
// Begin nsIURI support
//////////////////////////////////////////////////////////////////////////////

NS_IMETHODIMP nsMailtoUrl::GetSpec(nsACString& aSpec) {
  return m_baseURL->GetSpec(aSpec);
}

uint32_t nsMailtoUrl::SpecHash() {
  nsAutoCString spec;
  (void)GetSpec(spec);
  return CachedSpecHash(spec);
}
